// ── Render: Works ────────────────────────────────────────────────────────────
function renderWorks() {
  const grid = document.getElementById("works-grid");
  const dots = document.getElementById("works-dots");

  const visibleWorks = [
    WORKS[workIdx % WORKS.length],
    WORKS[(workIdx + 1) % WORKS.length],
    WORKS[(workIdx + 2) % WORKS.length],
  ];

  grid.innerHTML = visibleWorks.map(w => `
    <div class="green-glow-card work-card">
      <div class="work-card__img-wrap">
        <img src="${w.img}" alt="${w.title}" />
        <div class="work-card__idx"><span>${w.idx}</span></div>
      </div>
      <div class="work-card__body">
        <h3 class="font-syne work-card__title">${w.title}</h3>
        <p class="work-card__desc">${w.desc}</p>
        <a href="${w.url || '#'}" target="_blank" rel="noopener noreferrer" class="btn-outline-green work-card__btn">View project ${externalIconSVG}</a>
      </div>
    </div>
  `).join("");

  dots.innerHTML = WORKS.map((_, i) => `
    <button class="works__dot ${workIdx === i ? "active" : ""}" data-idx="${i}"></button>
  `).join("");

  dots.querySelectorAll(".works__dot").forEach(btn => {
    btn.addEventListener("click", () => {
      workIdx = parseInt(btn.dataset.idx, 10);
      renderWorks();
    });
  });
}

