// ── Render: Certificates ─────────────────────────────────────────────────────
function dataUriToBlobUrl(dataUri) {
  const [header, base64] = dataUri.split(",");
  const mimeMatch = header.match(/data:(.*?);base64/);
  const mime = mimeMatch ? mimeMatch[1] : "image/jpeg";
  const byteChars = atob(base64);
  const byteNumbers = new Array(byteChars.length);
  for (let i = 0; i < byteChars.length; i++) byteNumbers[i] = byteChars.charCodeAt(i);
  const byteArray = new Uint8Array(byteNumbers);
  const blob = new Blob([byteArray], { type: mime });
  return URL.createObjectURL(blob);
}

function renderCerts() {
  const grid = document.getElementById("certs-grid");
  grid.innerHTML = CERTS.map(c => `
    <div class="green-glow-card cert-card">
      <div class="cert-card__body">
        <h3 class="font-syne cert-card__title">${c.title}</h3>
        <div class="cert-card__org">${c.org}</div>
        <div class="cert-card__year">${c.year}</div>
        <a href="${c.url}" target="_blank" rel="noopener noreferrer" class="cert-card__link">View Certificate ${externalIconSVG}</a>
      </div>
    </div>
  `).join("");

  // Chrome blocks direct top-level navigation to data: URLs — convert those
  // certificate links to blob: URLs on click so the image actually opens.
  grid.querySelectorAll(".cert-card__link").forEach(link => {
    const href = link.getAttribute("href");
    if (href && href.startsWith("data:")) {
      link.addEventListener("click", e => {
        e.preventDefault();
        const blobUrl = dataUriToBlobUrl(href);
        window.open(blobUrl, "_blank", "noopener,noreferrer");
      });
    }
  });
}

// ── Hero typewriter animation ───────────────────────────────────────────────
function initTypewriter() {
  const el = document.getElementById("typewriter-text");
  if (!el) return;

  let roleIdx = 0;
  let displayed = "";
  let phase = "typing"; // "typing" | "pause" | "erasing"

  function tick() {
    const full = ROLES[roleIdx];
    let delay = 60;

    if (phase === "typing") {
      if (displayed.length < full.length) {
        displayed = full.slice(0, displayed.length + 1);
        delay = 60;
      } else {
        phase = "pause";
        delay = 1800;
      }
    } else if (phase === "pause") {
      phase = "erasing";
      delay = 300;
    } else {
      if (displayed.length > 0) {
        displayed = displayed.slice(0, -1);
        delay = 35;
      } else {
        roleIdx = (roleIdx + 1) % ROLES.length;
        phase = "typing";
        delay = 60;
      }
    }

    el.textContent = displayed;
    setTimeout(tick, delay);
  }

  tick();
}

// ── Theme toggle (dark / light) ─────────────────────────────────────────────
function initThemeToggle() {
  const btn = document.getElementById("theme-toggle-btn");
  if (!btn) return;

  const root = document.documentElement;
  const stored = localStorage.getItem("theme");
  const prefersLight = window.matchMedia && window.matchMedia("(prefers-color-scheme: light)").matches;
  const initial = stored || (prefersLight ? "light" : "dark");
  if (initial === "light") root.setAttribute("data-theme", "light");

  btn.addEventListener("click", () => {
    const isLight = root.getAttribute("data-theme") === "light";
    if (isLight) {
      root.removeAttribute("data-theme");
      localStorage.setItem("theme", "dark");
    } else {
      root.setAttribute("data-theme", "light");
      localStorage.setItem("theme", "light");
    }
  });
}

// ── Navbar scroll behavior ───────────────────────────────────────────────────
function initHeaderScroll() {
  const header = document.getElementById("header");
  const onScroll = () => {
    if (window.scrollY > 40) header.classList.add("scrolled");
    else header.classList.remove("scrolled");
  };
  window.addEventListener("scroll", onScroll);
  onScroll();
}

// ── Scroll-to & mobile menu ──────────────────────────────────────────────────
function initScrollTo() {
  const mobileMenu = document.getElementById("mobile-menu");

  function scrollTo(id) {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
    mobileMenu.classList.remove("open");
  }

  document.querySelectorAll("[data-target]").forEach(el => {
    el.addEventListener("click", () => scrollTo(el.dataset.target));
  });

  document.getElementById("logo-link").addEventListener("click", () => scrollTo("home"));

  document.getElementById("mobile-open-btn").addEventListener("click", () => {
    mobileMenu.classList.add("open");
  });
  document.getElementById("mobile-close-btn").addEventListener("click", () => {
    mobileMenu.classList.remove("open");
  });
}

// ── Explore-more button (hero) ───────────────────────────────────────────────
function initExploreMore() {
  const btn = document.getElementById("explore-more-btn");
  if (!btn) return;

  function jumpToNextSection() {
    const hero = document.getElementById("home");
    const sections = Array.from(document.querySelectorAll("section"));
    const heroIdx = sections.indexOf(hero);
    const next = sections[heroIdx + 1];
    if (next) next.scrollIntoView({ behavior: "smooth" });
  }

  btn.addEventListener("click", jumpToNextSection);
  btn.addEventListener("keydown", e => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      jumpToNextSection();
    }
  });
}

// ── Contact form ─────────────────────────────────────────────────────────────
const CONTACT_EMAIL = "zeeshanalam1261@gmail.com";

function initContactForm() {
  const form = document.getElementById("contact-form");
  const status = document.getElementById("contact-form-status");

  form.addEventListener("submit", e => {
    e.preventDefault();

    const name = document.getElementById("contact-name").value.trim();
    const email = document.getElementById("contact-email").value.trim();
    const subject = document.getElementById("contact-subject").value.trim();
    const message = document.getElementById("contact-message").value.trim();

    if (!name || !email || !message) {
      status.textContent = "Please fill in your name, email, and message.";
      status.classList.add("is-error");
      return;
    }

    const mailSubject = subject ? subject : `Portfolio inquiry from ${name}`;
    const mailBody =
      `Name: ${name}\n` +
      `Email: ${email}\n\n` +
      `${message}`;

    const gmailLink =
      `https://mail.google.com/mail/?view=cm&fs=1` +
      `&to=${encodeURIComponent(CONTACT_EMAIL)}` +
      `&su=${encodeURIComponent(mailSubject)}` +
      `&body=${encodeURIComponent(mailBody)}`;

    window.open(gmailLink, "_blank");

    status.classList.remove("is-error");
    status.textContent = "Opening Gmail to send this to Zeeshan…";
    form.reset();
  });
}

